function slots(events: FitnessEvent[]): FitnessSlot[] {
  const labels = ['Deadlift (MDL)', 'Hand-release push-up (HRP)', 'Sprint-drag-carry (SDC)', 'Plank (PLK)', '2-mile run (2MR)'];
  const ids = ['mdl', 'hrp', 'sdc', 'plk', '2mr'];
  return events.map((event, i) => ({ id: ids[i], label: labels[i], options: [event], minimumPoints: 60 }));
}

/** Combat standard: the M|C column, applied to every Soldier regardless of sex. */
function toCombat(event: FitnessEvent): FitnessEvent {
  return {
    ...event,
    brackets: event.brackets
      .filter((b) => b.sex === 'male')
      .map((b) => ({ ...b, sex: 'any' as const, points: b.points.map(([perf, pts]) => [perf, pts] as [number, number]) })),
  };
}

